  <script>
    // Carousel scroll
    function scrollCarousel(dir) {
      const carousel = document.getElementById('trendingCarousel');
      const scrollAmount = 300;
      carousel.scrollBy({ left: scrollAmount * dir, behavior: 'smooth' });
    }

    // Touch swipe for carousel
    const carousel = document.getElementById('trendingCarousel');
